#include <vector>

// Determines if the given stacks satisfy the "good" condition from the original algorithm.
// stacks[i] represents the (i+1)-th stack; stacks[i][0] is the bottom, stacks[i].back() is the top.
// Returns true if for every stack, no matching value appears after a non-matching value,
// and additionally for n==2, not both stacks contain a non-matching value.
bool isStackSortable(int n, const std::vector<std::vector<int>>& stacks) {
    if (n == 1) {
        for (int v : stacks[0]) {
            if (v != 1) return false;
        }
        return true;
    }

    std::vector<int> flag(n, 0);
    for (int i = 0; i < n; ++i) {
        for (int v : stacks[i]) {
            if (v != i + 1) {
                flag[i] = 1;
            } else {
                if (flag[i] == 1) {
                    flag[i] = 2;
                }
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        if (flag[i] == 2) return false;
    }

    if (n == 2) {
        if (flag[0] == 1 && flag[1] == 1) return false;
    }

    return true;
}
